#!/usr/bin/env ruby
# frozen_string_literal: true

# Codegen "middle path" (CLAUDE.md §5): generate the per-language table of PostgreSQL's quoted
# keywords (every keyword that is not unreserved) from the canonical spec/grammar/pg_keywords.toml.
# This emits the word list only — the lookup and the identifier-quoting rule that consult it
# (quote_ident, format's %I) stay hand-written in each core.
# Build-time only; no shipped core runs Ruby or parses TOML.
#
#   ruby scripts/gen_keywords.rb            # (re)write the generated files
#   ruby scripts/gen_keywords.rb --check    # fail if any checked-in file is stale
#
# Reasoning: spec/design/string-functions.md §3 and spec/design/codegen.md.

require "bundler/setup"
require "toml-rb"

REPO = File.expand_path("..", __dir__)
SRC = File.join(REPO, "spec", "grammar", "pg_keywords.toml")

TARGETS = [
  ["impl/rust/src/pg_keywords_gen.rs", :rust_file],
  ["impl/go/pg_keywords_gen.go",       :go_file],
  ["impl/ts/src/pg_keywords_gen.ts",   :ts_file],
].freeze

CATEGORIES = %w[reserved col_name type_func_name].freeze

def fail!(msg)
  warn "FAIL: #{msg}"
  exit 1
end

def load_words
  data = TomlRB.load_file(SRC)
  entries = data["keywords"]
  fail!("#{SRC}: no keywords") if entries.nil? || entries.empty?
  entries.each do |e|
    w = e["word"]
    fail!("#{SRC}: entry without a word") unless w.is_a?(String) && !w.empty?
    fail!("#{SRC}: #{w.inspect} is not lowercase ASCII letters and _") unless w.match?(/\A[a-z_]+\z/)
    fail!("#{SRC}: #{w}: unknown category #{e['category'].inspect}") unless CATEGORIES.include?(e["category"])
  end
  words = entries.map { |e| e["word"] }
  # Strictly ascending byte order: each core binary-searches the table.
  words.each_cons(2) do |a, b|
    fail!("#{a.inspect} must sort before #{b.inspect}") unless a.b < b.b
  end
  words
end

HEADER = <<~TXT.lines.map(&:chomp).freeze
  PostgreSQL's quoted keywords (CLAUDE.md §5): every PostgreSQL 18 keyword that is not an
  unreserved keyword (kwlist.h), as DATA. PostgreSQL's quote_identifier double-quotes an
  otherwise-safe identifier that is one of these words; the lookup that consults this table is
  hand-written. Regenerate with `mise run codegen`; `mise run verify` fails if this file is
  stale. Reasoning: spec/design/string-functions.md §3.
TXT

def rust_file(words)
  <<~RS
    // @generated by scripts/gen_keywords.rb from spec/grammar/pg_keywords.toml — DO NOT EDIT.
    //
    #{HEADER.map { |l| "// #{l}" }.join("\n")}

    /// The quoted keywords, in strictly ascending byte order (binary-searchable).
    #[rustfmt::skip]
    pub const QUOTED_KEYWORDS: &[&str] = &[
    #{words.map { |w| %(    "#{w}",) }.join("\n")}
    ];
  RS
end

def go_file(words)
  <<~GO
    // Code generated by scripts/gen_keywords.rb from spec/grammar/pg_keywords.toml. DO NOT EDIT.
    //
    #{HEADER.map { |l| "// #{l}" }.join("\n")}

    package jed

    // pgQuotedKeywords is the quoted keyword list, in strictly ascending byte order (binary-searchable).
    var pgQuotedKeywords = []string{
    #{words.map { |w| %(\t"#{w}",) }.join("\n")}
    }
  GO
end

def ts_file(words)
  <<~TS
    // @generated by scripts/gen_keywords.rb from spec/grammar/pg_keywords.toml — DO NOT EDIT.
    //
    #{HEADER.map { |l| "// #{l}" }.join("\n")}

    // The quoted keywords, in strictly ascending byte order.
    export const QUOTED_KEYWORDS: ReadonlySet<string> = new Set([
    #{words.map { |w| %(  "#{w}",) }.join("\n")}
    ]);
  TS
end

def main
  check = ARGV.include?("--check")
  words = load_words
  stale = []
  TARGETS.each do |rel, builder|
    path = File.join(REPO, rel)
    content = send(builder, words)
    if check
      current = File.exist?(path) ? File.read(path) : nil
      stale << rel unless current == content
    else
      File.write(path, content)
      puts "wrote #{rel}"
    end
  end
  return unless check

  unless stale.empty?
    stale.each { |rel| warn "STALE: #{rel} — run 'mise run codegen'" }
    exit 1
  end
  puts "OK: #{TARGETS.length} generated files current (#{words.length} quoted keywords)"
end

main
